window.WORLDART = (() => {
  const A = window.ART;
  const D = window.GAME_DATA;
  const { p, ellipse, glow, hash, hero, stand } = A;
  const TAU = Math.PI * 2;

  const TILE = {
    GRASS: 0, PATH: 1, WATER: 2, TREE: 3, STONE: 4, SAND: 5, ROCK: 6,
