  function isSolid(m, px, py) {
    const tx = Math.floor(px / TS), ty = Math.floor(py / TS);
    if (tx < 0 || ty < 0 || tx >= m.w || ty >= m.h) return true;
    if (m.solid[ty * m.w + tx]) return true;
    for (const o of m.objects) {
      if (!o.solid) continue;
