295:   /* ---------------------------- hero / progression ---------------------------- */
296:   function heroStats(id, hero = null) {
297:     const c = D.CHARACTERS[id];
298:     const h = hero || G.state?.heroes?.[id] || newHero(id);
299:     const lv = h.level || 1;
300:     let maxHp = c.base.hp + c.growth.hp * (lv - 1);
301:     let atk = c.base.atk + c.growth.atk * (lv - 1);
302:     let def = c.base.def + c.growth.def * (lv - 1);
303:     let speed = c.base.speed + c.growth.speed * (lv - 1);
304:     let maxEnergy = c.base.energy + c.growth.energy * (lv - 1);
305:     let crit = c.base.crit;
306:     let critDmg = c.base.critDmg;
307:     let cdMult = 1, skill1Mult = 1, skill2Mult = 1, ultMult = 1;
308:     const nodes = h.skillNodes || [];
309:     for (const node of D.TREE_NODES) {
310:       if (!nodes.includes(node.id)) continue;
311:       const e = node.effect;
312:       if (e.maxHp) maxHp += e.maxHp;
313:       if (e.atk) atk += e.atk;
314:       if (e.def) def += e.def;
315:       if (e.speed) speed += e.speed;
316:       if (e.maxEnergy) maxEnergy += e.maxEnergy;
317:       if (e.crit) crit += e.crit;
318:       if (e.cd) cdMult *= e.cd;
319:       if (e.skill1) skill1Mult *= e.skill1;
320:       if (e.skill2) skill2Mult *= e.skill2;
321:       if (e.ultimate) ultMult *= e.ultimate;
322:     }
323:     // permanent charm
324:     if ((G.state?.items?.charm || 0) > 0) speed += 6;
325:     if (id === 'jotaro') { crit += 0.15; critDmg += 0.1; }
326:     if (id === 'joseph') cdMult *= 0.9;
327:     if (id === 'jonathan') { /* passive handled in damage */ }
328:     maxHp = Math.round(maxHp); atk = Math.round(atk * 10) / 10; def = Math.round(def * 10) / 10;
329:     speed = Math.round(speed * 10) / 10; maxEnergy = Math.round(maxEnergy);
330:     crit = Math.min(0.75, crit); critDmg = Math.round(critDmg * 100) / 100;
331:     return { maxHp, atk, def, speed, maxEnergy, crit, critDmg, cdMult, skill1Mult, skill2Mult, ultMult };
332:   }
