334:   function gainXP(amount) {
335:     if (!G.state) return;
336:     const h = G.state.heroes[G.state.activeHero];
337:     if (!h) return;
338:     if (h.level >= D.MAX_LEVEL) { h.xp = 0; return; }
339:     h.xp += amount;
340:     h.totalXp = (h.totalXp || 0) + amount;
341:     let leveled = 0;
342:     while (h.level < D.MAX_LEVEL && h.xp >= D.XP_TABLE[h.level]) {
343:       h.xp -= D.XP_TABLE[h.level];
344:       h.level++;
345:       h.sp++;
346:       leveled++;
347:     }
348:     if (leveled > 0) {
349:       const st = heroStats(h.id, h);
350:       h.hp = st.maxHp;
351:       G.showLevelUp(h.id, h.level);
352:       if (window.SOUND) SOUND.sfx('level');
353:       G.save(true);
354:     }
355:   }
