373:   function useItem(item) {
374:     if (!G.state) return false;
375:     const def = D.ITEMS[item];
376:     if (!def) return false;
377:     const h = G.state.heroes[G.state.activeHero];
378:     const st = heroStats(h.id, h);
379:     if (def.type === 'heal') {
380:       if (h.hp >= st.maxHp) { toast(tr('ui.fullHp'), 'bad'); return false; }
381:       h.hp = Math.min(st.maxHp, h.hp + def.heal);
382:       removeItem(item);
383:       toast(`${itemName(item)}: +${def.heal} ${tr('ui.hp')}`, 'good');
384:       if (window.SOUND) SOUND.sfx('heal');
385:     } else if (def.type === 'energy') {
386:       G.runtime.player.energy = Math.min(st.maxEnergy, G.runtime.player.energy + def.energy);
387:       removeItem(item);
388:       toast(`${itemName(item)}: +${def.energy} ${tr('ui.energy')}`, 'good');
389:       if (window.SOUND) SOUND.sfx('heal');
390:     } else if (def.type === 'buff') {
391:       if (def.buff.speed) addBuff({ type: 'speed', mult: def.buff.speed, duration: def.buff.duration, nameKey: 'ui.buffSpeed' });
392:       removeItem(item);
393:       toast(`${itemName(item)}`, 'good');
394:       if (window.SOUND) SOUND.sfx('heal');
395:     } else if (def.type === 'permanent') {
396:       // charm stays in inventory as proof but effect applies permanently
397:       toast(tr('ui.itemUsed') + ': ' + itemName(item), 'good');
398:       if (window.SOUND) SOUND.sfx('level');
399:       G.save(true);
400:       return true;
401:     } else {
402:       toast(tr('ui.noNeed'), 'bad');
403:       return false;
404:     }
405:     G.refreshHUD();
406:     if (window.UI) UI.refreshMenu();
407:     save(true);
408:     return true;
409:   }
