739:   function hitEnemiesInCone(x, y, dir, range, arc, power, opts = {}) {
740:     const r = G.runtime, p = r.player, st = p.stats;
741:     let any = false;
742:     for (const e of r.enemies) {
743:       if (e.dead) continue;
744:       const dx = e.x - x, dy = e.y - (y + 6);
745:       const d = Math.hypot(dx, dy);
746:       if (d > range + e.radius) continue;
747:       const dot = (dx * dir.x + dy * dir.y) / (d || 1);
748:       if (dot < Math.cos(arc)) continue;
749:       const crit = Math.random() < st.crit;
750:       let dmg = st.atk * power * (hasBuff('dmg') ? buffMult('dmg') : 1) * (1 + (p.stats.skill1Mult - 1) * 0);
751:       if (crit) dmg *= st.critDmg;
752:       dmg *= 1 - (e.def.def || 0) / ((e.def.def || 0) + 55);
753:       damageEnemy(e, Math.max(1, Math.round(dmg)), { crit, x: e.x, y: e.y - 12, stand: opts.stand });
754:       any = true;
755:     }
756:     return any;
757:   }
