759:   function damageArea(x, y, radius, power, opts = {}) {
760:     const r = G.runtime, p = r.player, st = p.stats;
761:     let any = false;
762:     for (const e of r.enemies) {
763:       if (e.dead) continue;
764:       const d = Math.hypot(e.x - x, e.y - y);
765:       if (d > radius + e.radius) continue;
766:       const crit = Math.random() < st.crit;
767:       let dmg = st.atk * power * (hasBuff('dmg') ? buffMult('dmg') : 1);
768:       if (crit) dmg *= st.critDmg;
769:       dmg *= 1 - (e.def.def || 0) / ((e.def.def || 0) + 55);
770:       damageEnemy(e, Math.max(1, Math.round(dmg)), { crit, x: e.x, y: e.y - 12, color: opts.color });
771:       if (opts.stun) e.stun = Math.max(e.stun, opts.stun);
772:       if (opts.knockback) {
773:         const a = Math.atan2(e.y - y, e.x - x);
774:         const kb = opts.knockback;
775:         for (let i = 0; i < 6; i++) {
776:           const nx = e.x + Math.cos(a) * kb * 0.016, ny = e.y + Math.sin(a) * kb * 0.016;
777:           if (canStand(nx, ny, e.radius)) { e.x = nx; e.y = ny; } else break;
778:         }
779:       }
780:       any = true;
781:     }
782:     return any;
783:   }
