792:       const t = Math.max(0, Math.min(1, ((e.x - x1) * dx + (e.y - y1) * dy) / (len * len)));
793:       const px = x1 + dx * t, py = y1 + dy * t;
794:       if (Math.hypot(e.x - px, e.y - py) > radius + e.radius) continue;
795:       const crit = Math.random() < st.crit;
