797:       if (crit) dmg *= st.critDmg;
798:       dmg *= 1 - (e.def.def || 0) / ((e.def.def || 0) + 55);
799:       damageEnemy(e, Math.max(1, Math.round(dmg)), { crit, x: e.x, y: e.y - 12 });
