919:   function updateProjectiles(dt) {
920:     const r = G.runtime, p = r.player;
921:     for (const pr of r.projectiles) {
922:       if (pr.delay > 0) { pr.delay -= dt; continue; }
923:       pr.life -= dt;
924:       pr.x += pr.vx * dt; pr.y += pr.vy * dt;
925:       if (pr.boomerang) {
926:         if (!pr.returning) {
927:           if (Math.hypot(pr.x - pr.origin.x, pr.y - pr.origin.y) > pr.range) {
928:             pr.returning = true; pr.hitSet.clear();
929:           }
930:         } else {
931:           const dx = p.x - pr.x, dy = (p.y - 12) - pr.y, d = Math.hypot(dx, dy) || 1;
932:           pr.vx = dx / d * 300; pr.vy = dy / d * 300;
933:           if (d < 14) { pr.life = 0; }
934:         }
935:       }
936:       if (pr.owner === 'player') {
937:         for (const e of r.enemies) {
938:           if (e.dead || pr.hitSet.has(e)) continue;
939:           if (Math.hypot(e.x - pr.x, e.y - 10 - pr.y) < 13 + e.radius) {
940:             pr.hitSet.add(e);
941:             const st = p.stats;
942:             let dmg = pr.damage;
943:             if (Math.random() < st.crit) dmg *= st.critDmg;
944:             dmg *= 1 - (e.def.def || 0) / ((e.def.def || 0) + 55);
945:             damageEnemy(e, Math.max(1, Math.round(dmg)), { crit: false, x: e.x, y: e.y - 12 });
946:             addParticles(pr.x, pr.y, 4, pr.color);
947:             if (!pr.pierce && !pr.boomerang) { pr.life = 0; break; }
948:           }
949:         }
950:       } else {
951:         if (p.invuln <= 0 && Math.hypot(p.x - pr.x, p.y - 10 - pr.y) < 12) {
952:           damagePlayer(pr.damage, pr);
953:           pr.life = 0;
954:         }
955:       }
956:       if (pr.life <= 0) continue;
957:       if (W.isSolid(r.world, pr.x, pr.y)) pr.life = 0;
958:       if (Math.random() < 0.35) addParticle(pr.x, pr.y, 0, 0, 0.18, pr.color, 1);
959:     }
960:     r.projectiles = r.projectiles.filter(pr => pr.life > 0);
