  dialogue: {
    speedwagon_intro: [
      { speaker: 'speedwagon', text: 'Святой угодники! Ты и есть юный Джостар? Я — Роберт Э. О. Спидвагон, и у меня плохие новости.' },
      { speaker: 'speedwagon', text: 'Каменная маска в поместье пробудила Дио. Теперь по округе бродят зомби, а деревня дрожит от страха.' },
      { speaker: 'speedwagon', text: 'Начни с кладбища на западе. Там собираются мертвецы. И, парень... не умирай. Это будет ужасно для репутации.' }
    ],
    speedwagon_after: [
      { speaker: 'speedwagon', text: 'Лондонский воздух был чище, но и тут неплохо. Если увидишь что-то странное — бей первым, спрашивай потом.' },
      { speaker: 'speedwagon', text: 'Кстати, я потерял бухгалтерскую книгу на кладбище. Если найдёшь — я щедро отблагодарю. Очень щедро. Наверное.' }
    ],
    speedwagon_ledger_offer: [
      { speaker: 'speedwagon', text: 'Вот в чём дело: моя бухгалтерская книга осталась среди могил. Без неё я не могу оплатить даже чай.' },
      { speaker: 'speedwagon', text: 'Найди её, и я отдам тебе всё, что у меня есть. Ну, кроме шляпы. Шляпа — это святое.' }
    ],
    speedwagon_ledger_done: [
      { speaker: 'speedwagon', text: 'Моя книга! Ты настоящий герой, парень. Держи награду и никому не рассказывай, сколько я на самом деле зарабатываю.' }
    ],
    erina_intro: [
      { speaker: 'erina', text: 'Джонатан... то есть, ты. Прости, я всё ещё думаю о нём. Дио вернулся в поместье, и от него веет чем-то холодным.' },
      { speaker: 'erina', text: 'Возьми это. И будь осторожен. Настоящая сила не в кулаках, а в сердце, которое не отступает.' },
      { speaker: 'erina', text: 'Если найдёшь лунные травы в саду, принеси мне. Я смогу приготовить лекарство для раненых.' }
    ],
    erina_after: [
      { speaker: 'erina', text: 'Я верю, что ты справишься. Даже в самые тёмные времена солнце возвращается.' }
    ],
    erina_herbs_offer: [
      { speaker: 'erina', text: 'Мне нужно три лунные травы. Они светятся голубым в темноте — их легко заметить в саду и у реки.' },
      { speaker: 'erina', text: 'Это для лекарства. Не для салата. Пожалуйста, не перепутай.' }
    ],
    erina_herbs_done: [
      { speaker: 'erina', text: 'Ты собрал их все! Теперь у меня есть надежда. Возьми эти припасы — и, пожалуйста, береги себя.' }
    ],
    dio_intro: [
      { speaker: 'dio', text: 'А, Джостар. Ты пришёл в мой дом, словно мотылёк к пламени. Как трогательно.' },
      { speaker: 'dio', text: 'Каменная маска дала мне силу, о которой ты можешь только мечтать. Преклонись — и я, возможно, оставлю тебе жизнь.' },
      { speaker: 'dio', text: 'Нет? Что ж. Тогда я выпью твою кровь и забуду твоё имя к утру.' }
    ],
    dio_defeat: [
      { speaker: 'dio', text: 'Невозможно... я... бессмертный...' },
      { speaker: 'dio', text: 'Ты... всего лишь... человек...' }
    ],
    hamon_awaken: [
      { speaker: 'hero', text: 'Дыхание... я чувствую его. Солнечный свет течёт по моим венам, словно река.' },
      { speaker: 'hero', text: 'Это Хамо́н. Теперь тьма не сможет меня коснуться.' }
    ],
    caesar_intro: [
      { speaker: 'caesar', text: 'Ты опоздал. Но я прощу тебя, если ты хотя бы умеешь дышать правильно.' },
      { speaker: 'caesar', text: 'Меня зовут Цезарь Цеппели. Хамо́н — не трюк, а искусство. И у нас мало времени.' },
      { speaker: 'caesar', text: 'Каменные культисты захватили руины. Победи их, и я покажу тебе настоящую технику.' }
    ],
    caesar_after: [
      { speaker: 'caesar', text: 'Твоё дыхание стало ровнее. Не идеально, но уже не позорно. Продолжай тренироваться.' }
    ],
    caesar_trial_offer: [
      { speaker: 'caesar', text: 'В руинах спрятаны два древних свитка. Принеси их, и я научу тебя технике, которую не показывают туристам.' },
      { speaker: 'caesar', text: 'И не называй это квестом. Это испытание. Разница принципиальная.' }
    ],
    caesar_trial_done: [
      { speaker: 'caesar', text: 'Отлично. Теперь ты понимаешь, что сила — это ещё и знание. Держи, ты заслужил.' }
    ],
    wamuu_intro: [
      { speaker: 'wamuu', text: 'Ты осмелился войти в мой храм. Ветер принёс твой запах, человек.' },
      { speaker: 'wamuu', text: 'Я — Вамуу, воин ветра. Покажи мне свою силу, или исчезни, как пыль.' }
    ],
    wamuu_defeat: [
      { speaker: 'wamuu', text: 'Достойно... Ты сражался как воин. Я признаю твою силу.' }
    ],
    elder_intro: [
      { speaker: 'elder', text: 'Сын пустыни, ты пришёл в час, когда древние камни снова дрожат.' },
      { speaker: 'elder', text: 'Под пирамидой спит Эйсидиси. Его пламя пьёт тепло из песка. Останови его, пока пустыня не стала пеплом.' },
      { speaker: 'elder', text: 'И помни: камень терпелив, но солнце — тоже.' }
    ],
    elder_after: [
      { speaker: 'elder', text: 'Путь ведёт на восток, через море. Каир ждёт тебя, странник.' }
    ],
    esidisi_intro: [
      { speaker: 'esidisi', text: 'Ты пришёл с огнём в глазах. Как забавно. Я тоже люблю огонь.' },
      { speaker: 'esidisi', text: 'Я — Эйсидиси. И я буду пировать, пока от твоей пустыни не останется только пепел.' }
    ],
    esidisi_defeat: [
      { speaker: 'esidisi', text: 'Невозможно... моё пламя... гаснет...' }
    ],
    avdol_intro: [
      { speaker: 'avdol', text: 'Джотаро, ты наконец здесь. Каир кишит врагами, а Дио скрывается в своём поместье на севере.' },
      { speaker: 'avdol', text: 'Его слуги — Стэнды. Не стоит недооценивать их. Особенно того, кто пьёт кровь из теней.' },
      { speaker: 'avdol', text: 'Сначала зачисти улицы. Восемь убийц. Потом мы нанесём последний удар.' }
    ],
    avdol_after: [
      { speaker: 'avdol', text: 'Ты стал сильнее. Но помни: победа над Дио — это не только сила. Это воля.' }
    ],
    polnareff_intro: [
      { speaker: 'polnareff', text: 'Эй, ты! Да, ты. У меня к тебе дело. Точнее, к твоим кулакам.' },
      { speaker: 'polnareff', text: 'Убийцы со Стэндами прячутся по всему Каиру. Помоги мне отправить их к праотцам. Я заплачу. И по-дружески угощу.' }
    ],
    polnareff_done: [
      { speaker: 'polnareff', text: 'Отличная работа! Может, из тебя выйдет толк. Держи оберег — он приносит удачу. Наверное.' }
    ],
    kakyoin_ambient: [
      { speaker: 'kakyoin', text: 'Этот город похож на лабиринт. Каждый переулок может стать ловушкой. Будь внимателен.' },
      { speaker: 'kakyoin', text: 'И не ешь местную шаурму перед битвой. Проверено. Дважды.' }
    ],
    iggy_offer: [
      { speaker: 'iggy', text: 'Гав. (Перевод: «Мне нужна кофейная жвачка. Две. И не смотри на меня так.»)' },
      { speaker: 'iggy', text: 'Гав-гав. (Перевод: «Если найдёшь — я, так и быть, не буду кусать твои ботинки. Сегодня.»)' }
