content.text:
Now create ui.js. This is big. Let's write carefully.

Key issue: `G.tr` path returns object for quests.main etc. We'll use directly.

Speaker names map.

UI state:
```
const UI={ menuTab:'heroes', menuHero:null, dlg:{...}, lastMap:0 };
window.UI=UI;
```

Dialogue typewriter:
```
let dlgState=null;
function speakerId(sp){ if(sp==='hero') return G.state.activeHero; return sp; }
function speakerName(sp){...}
UI.showDialogue=function(lines,onDone){
 if(!lines||!lines.length){ onDone&&onDone(); return;}
 dlgState={lines,idx:0,onDone,char:0,typing:false,timer:null,full:''};
 G.runtime.dialogueOpen=true;
 G.setPaused(true);
 $('#dialogue').classList.remove('hidden');
 renderDlgLine();
}
function renderDlgLine(){
 const line=dlgState.lines[dlgState.idx];
 const id=speakerId(line.speaker);
 $('#dlg-name').textContent=speakerName(line.speaker);
 const cv=$('#dlg-portrait'); const ctx=cv.getContext('2d'); ctx.clearRect; ctx.drawImage(ART.portraitCanvas(id),0,0,128,128);
 const text=line.text;
 dlgState.full=text; dlgState.char=0; dlgState.typing=true;
 $('#dlg-text').textContent='';
 clearInterval(dlgState.timer);
 dlgState.timer=setInterval(()=>{
   dlgState.char += 2; // speed
   $('#dlg-text').textContent=text.slice(0,dlgState.char);
   if(dlgState.char>=text.length){ clearInterval; dlgState.typing=false; }
 },22);
}
function advanceDialogue(){
 if(!dlgState) return;
 if(dlgState.typing){ clearInterval; dlgState.typing=false; $('#dlg-text').textContent=dlgState.full; return;}
 dlgState.idx++;
 if(dlgState.idx>=lines.length){ finishDialogue(); } else renderDlgLine();
}
function finishDialogue(){ const cb=dlgState.onDone; clearInterval; dlgState=null; $('#dialogue').classList.add('hidden'); G.runtime.dialogueOpen=false; if(G.runtime.inGame&&!G.runtime.menuOpen&&!G.runtime.death&&!G.runtime.ending) G.setPaused(false); if(cb) setTimeout(cb,50); }
```
But finishDialogue calls setPaused(false) before callback; callback may show another dialogue and pause again. Fine. However if callback opens boss spawn, okay. Use setTimeout 60 to avoid recursion and let unpause. But if callback shows chapter intro, it pauses. Good.

Need `UI.isDialogueOpen` maybe.

Bind `#dialogue` click -> advance. Keyboard.

Update HUD:
```
UI.updateHUD=function(force){
 const r=G.runtime; if(!r.inGame||!r.player||!G.state) return;
 const now=performance.now();
 if(!force && now-(r.uiRefresh||0)<90) return;
 r.uiRefresh=now;
 ...
}
```
Need when paused UI update force from actions.

HP text use Math.ceil.

Stance: jotaro -> tr('ui.stanceStand') else tr('ui.stanceHamon').

Weather: use r.weather or D.WEATHERS; label keys `ui.weatherRain` etc. For mexico/egypt heat -> weatherHeat; england rain; italy clear.

Quest tracker:
```
const st=G.mainStage();
$('#quest-chapter').textContent=G.chapterTitle(st.chapter) maybe tr('quests.chapters.c'+ch)
```
G.chapterTitle(ch) returns tr('quests.chapters.c'+ch). Good.
- If st.kind==='free', maybe show side quest if active/ready. Else main.
- `$('#quest-name').textContent = q.name`
- objective: q.obj + progress
- progress from STORY.questProgress()
- compass.
For free with no side -> q.obj.

Side active target: STORY.activeSide? We'll implement `STORY.displayQuest()` returns {name, obj, chapter, progress}. Better UI can use STORY. But simpler: in UI:
```
let q=G.questDef(); let progress=STORY.questProgress?STORY.questProgress():'';
```
For free, if STORY.activeSideQuest() returns id, use side def.

We'll implement `STORY.tracker()` returning {name,obj,chapter,progress}. Then UI uses it. Need define in story.js. Good.

Compass:
```
const qt=STORY.questTarget();
if(qt){ const dx=qt.x-player.x; ...; deg=atan2(dy,dx)*180/PI+90; arrow.style.transform=`rotate(${deg}deg)`; distance=Math.max(1,Math.round(dist/8)) + ' ' + tr('ui.distanceUnit');}
else arrow transform rotate(0); distance='—'
```
If target is current? fine.

Minimap throttle: if force || now-lastMap>250 -> ENGINE.drawMinimap($('#minimap')); lastMap=now.

Boss:
```
if(r.bossActive&&!r.bossActive.dead){ show; name; phase; fill width; } else hide
```
But UI.hideBoss may be called on start. If boss bar hidden class.

Skill buttons: refreshSkillLabels sets labels/icons. refreshSkillButtons uses runtime.cd and player.energy.
```
const hero=G.state.activeHero; const c=D.CHARACTERS[hero];
for i: btn=document.querySelector(`#btn-skill-${i}`); ...
 const sk=c.skills[i]; const cd=G.runtime.cd[i]||0;
 btn.classList.toggle('cooling',cd>0);
 btn.classList.toggle('no-energy', energy<sk.energy);
 btn.querySelector('.cd-text').textContent=cd>0?cd.toFixed(1):'';
```
Need `.cd-ring` uses conic gradient? CSS probably uses custom property. Check CSS lines 562-573.

